-- Hồ sơ CRM: RFM theo tổng tiền đã giao; LTV theo năm lịch × lifespan.
UPDATE users u
SET
    total_orders = COALESCE(s.cnt, 0),
    ltv = COALESCE(s.ltv, 0),
    last_purchase_at = s.last_at,
    rfm_segment = CASE
        WHEN s.r BETWEEN 4 AND 5 AND s.f BETWEEN 4 AND 5 AND s.m BETWEEN 4 AND 5 THEN 'champions'
        WHEN s.r BETWEEN 2 AND 5 AND s.f BETWEEN 3 AND 5 AND s.m BETWEEN 3 AND 5 THEN 'loyal'
        WHEN s.r BETWEEN 1 AND 2 AND s.f BETWEEN 3 AND 5 AND s.m BETWEEN 3 AND 5 THEN 'at_risk'
        WHEN s.r BETWEEN 3 AND 5 AND s.f BETWEEN 1 AND 3 AND s.m BETWEEN 1 AND 3 THEN 'potential'
        WHEN s.r BETWEEN 1 AND 2 AND s.f BETWEEN 1 AND 2 AND s.m BETWEEN 1 AND 2 THEN 'lost'
        ELSE 'other'
    END,
    loyalty_balance = COALESCE(s.cnt, 0) * 50,
    loyalty_tier = CASE
        WHEN COALESCE(s.spend, 0) >= 8000000 THEN 'platinum'
        WHEN COALESCE(s.spend, 0) >= 4000000 THEN 'gold'
        WHEN COALESCE(s.spend, 0) >= 1500000 THEN 'silver'
        ELSE 'bronze'
    END,
    wallet_balance = CASE WHEN COALESCE(s.spend, 0) >= 4000000 THEN 250000 ELSE 0 END
FROM (
    SELECT
        u2.id AS user_id,
        COALESCE(s.cnt, 0) AS cnt,
        COALESCE(s.spend, 0) AS spend,
        COALESCE(s.ltv, 0) AS ltv,
        s.last_at,
        CASE
            WHEN s.last_at IS NULL OR CURRENT_DATE - s.last_at > 180 THEN 1
            WHEN CURRENT_DATE - s.last_at <= 30 THEN 5
            WHEN CURRENT_DATE - s.last_at <= 60 THEN 4
            WHEN CURRENT_DATE - s.last_at <= 90 THEN 3
            ELSE 2
        END AS r,
        CASE
            WHEN COALESCE(s.cnt, 0) <= 1 THEN 1
            WHEN s.cnt = 2 THEN 2
            WHEN s.cnt <= 4 THEN 3
            WHEN s.cnt <= 7 THEN 4
            ELSE 5
        END AS f,
        CASE
            WHEN COALESCE(s.spend, 0) < 500000 THEN 1
            WHEN s.spend < 1500000 THEN 2
            WHEN s.spend < 4000000 THEN 3
            WHEN s.spend < 8000000 THEN 4
            ELSE 5
        END AS m
    FROM users u2
    LEFT JOIN (
        SELECT
            user_id,
            COUNT(*)::int AS cnt,
            SUM(total_amount) AS spend,
            MIN(created_at)::date AS first_at,
            MAX(created_at)::date AS last_at,
            ROUND(
                COALESCE(SUM(total_amount) FILTER (
                    WHERE EXTRACT(YEAR FROM created_at) = EXTRACT(YEAR FROM CURRENT_DATE)
                ), 0)
                * CASE
                    WHEN MIN(created_at)::date IS NULL THEN 0
                    WHEN MAX(created_at)::date <= MIN(created_at)::date THEN 1
                    ELSE (MAX(created_at)::date - MIN(created_at)::date)::numeric / 365
                END
            , 2) AS ltv
        FROM orders
        WHERE status = 'delivered'
        GROUP BY user_id
    ) s ON s.user_id = u2.id
    WHERE NOT EXISTS (SELECT 1 FROM employees e WHERE e.user_id = u2.id)
) s
WHERE u.id = s.user_id;



