INSERT INTO conversation_messages (id, conversation_id, sender_id, content, sent_at) VALUES
    ('b2000001-0000-4000-8000-000000000001', 'b1000001-0000-4000-8000-000000000001', 'aaaa1111-1111-1111-1111-111111111111', 'Mình muốn hỏi tình trạng đơn và bảo hành.', now() - interval '2 hours'),
    ('b2000001-0000-4000-8000-000000000002', 'b1000001-0000-4000-8000-000000000001', '33333333-3333-3333-3333-333333333333', 'Em đã nhận yêu cầu, đang kiểm tra đơn giúp anh.', now() - interval '1 hours'),
    ('b2000001-0000-4000-8000-000000000003', 'b1000001-0000-4000-8000-000000000002', 'bbbb2222-2222-2222-2222-222222222222', 'Đơn đĩa game của mình giao chậm hơn dự kiến.', now() - interval '50 minutes'),
    ('b2000001-0000-4000-8000-000000000004', 'b1000001-0000-4000-8000-000000000002', '33333333-3333-3333-3333-333333333333', 'Em đang hỏi kho và sẽ báo lại sớm.', now() - interval '40 minutes'),
    ('b2000001-0000-4000-8000-000000000005', 'b1000001-0000-4000-8000-000000000003', 'dddd4444-4444-4444-4444-444444444444', 'Tay cầm DualSense bị trôi analog, mình muốn đổi bảo hành gấp.', now() - interval '2 days'),
    ('b2000001-0000-4000-8000-000000000006', 'b1000001-0000-4000-8000-000000000003', '33333333-3333-3333-3333-333333333333', 'Em đã chuyển bảo hành, đang chờ phản hồi từ kho.', now() - interval '2 days' + interval '30 minutes'),
    ('b2000001-0000-4000-8000-000000000007', 'b1000001-0000-4000-8000-000000000004', 'eeee5555-5555-5555-5555-555555555555', 'Mình muốn hỏi tình trạng bảo hành tai nghe.', now() - interval '3 hours'),
    ('b2000001-0000-4000-8000-000000000008', 'b1000001-0000-4000-8000-000000000004', '33333333-3333-3333-3333-333333333333', 'Em đã ghi nhận, sẽ phản hồi trong ngày.', now() - interval '2 hours'),
    ('b2000001-0000-4000-8000-000000000009', 'b1000001-0000-4000-8000-000000000005', '77777777-7777-7777-7777-777777777777', 'Đơn hàng của mình sắp tới hạn giao, shop xác nhận giúp mình với.', now() - interval '3 hours 50 minutes'),
    ('b2000001-0000-4000-8000-000000000010', 'b1000001-0000-4000-8000-000000000005', '33333333-3333-3333-3333-333333333333', 'Em đang kiểm tra vận đơn giúp chị.', now() - interval '30 minutes'),
    ('b2000001-0000-4000-8000-000000000011', 'b1000001-0000-4000-8000-000000000006', 'c1000001-0000-4000-8000-000000000001', 'Mình muốn hỏi tình trạng đơn và bảo hành.', now() - interval '6 days'),
    ('b2000001-0000-4000-8000-000000000012', 'b1000001-0000-4000-8000-000000000006', '33333333-3333-3333-3333-333333333333', 'Em đã xử lý xong và đóng yêu cầu.', now() - interval '5 days');
